import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor cute_matmul(torch::Tensor A, torch::Tensor B);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

#define BM 128
#define BN 128
#define BK 32
#define TM 8
#define TN 8
#define COLTILES 2
#define PAD_B 4  // padding to break bank-conflict periodicity (BN==128 is a multiple of 32 banks)
#define SM_A_STRIDE (BK + 4)
#define SM_B_STRIDE (BN + PAD_B)
__global__ void cute_matmul_kernel(
    const float* __restrict__ A,
    const float* __restrict__ B,
    float* __restrict__ C,
    int M, int N, int K)
{
    extern __shared__ float smem[];
    float* As = smem;                              // [BM][SM_A_STRIDE]
    float* Bs = As + (size_t)BM * SM_A_STRIDE;      // [2][BK][SM_B_STRIDE] double-buffered
    const int tx = threadIdx.x; // 0..15
    const int ty = threadIdx.y; // 0..15
    const int tid = ty * blockDim.x + tx; // 0..255
    const int numThreads = blockDim.x * blockDim.y;
    const int blockRow = blockIdx.y * BM;
    const int colBase = blockIdx.x * BN * COLTILES;
    float acc[COLTILES][TM][TN];
    #pragma unroll
    for (int c = 0; c < COLTILES; ++c)
        #pragma unroll
        for (int i = 0; i < TM; ++i)
            #pragma unroll
            for (int j = 0; j < TN; ++j)
                acc[c][i][j] = 0.f;
    int numTiles = (K + BK - 1) / BK;
    for (int t = 0; t < numTiles; ++t) {
        int kBase = t * BK;
        // Load A tile (BM x BK) into shared memory once per K-tile; reused across all COLTILES N-tiles
        const int numAvec = (BM * BK) / 4;
        for (int i = tid; i < numAvec; i += numThreads) {
            int row = (i * 4) / BK;
            int colBaseA = (i * 4) % BK;
            int globalRow = blockRow + row;
            int globalCol = kBase + colBaseA;
            float4 val = make_float4(0.f, 0.f, 0.f, 0.f);
            if (globalRow < M) {
                if (globalCol + 3 < K) {
                    val = *reinterpret_cast<const float4*>(&A[(size_t)globalRow * K + globalCol]);
                } else {
                    float tmp[4] = {0.f, 0.f, 0.f, 0.f};
                    #pragma unroll
                    for (int j = 0; j < 4; ++j) {
                        int cA = globalCol + j;
                        if (cA < K) tmp[j] = A[(size_t)globalRow * K + cA];
                    }
                    val = make_float4(tmp[0], tmp[1], tmp[2], tmp[3]);
                }
            }
            *reinterpret_cast<float4*>(&As[row * SM_A_STRIDE + colBaseA]) = val;
        }
        // Load first B tile (for c == 0) into buffer 0, together with the A tile load above;
        // a single syncthreads below covers both loads (software pipelining / prefetch setup).
        {
            int blockCol0 = colBase + 0 * BN;
            float* dst = Bs; // buffer 0
            const int numBvec = (BK * BN) / 4;
            for (int i = tid; i < numBvec; i += numThreads) {
                int row = (i * 4) / BN;
                int colBaseB = (i * 4) % BN;
                int globalRow = kBase + row;
                int globalCol = blockCol0 + colBaseB;
                float4 val = make_float4(0.f, 0.f, 0.f, 0.f);
                if (globalRow < K) {
                    if (globalCol + 3 < N) {
                        val = *reinterpret_cast<const float4*>(&B[(size_t)globalRow * N + globalCol]);
                    } else {
                        float tmp[4] = {0.f, 0.f, 0.f, 0.f};
                        #pragma unroll
                        for (int j = 0; j < 4; ++j) {
                            int cc = globalCol + j;
                            if (cc < N) tmp[j] = B[(size_t)globalRow * N + cc];
                        }
                        val = make_float4(tmp[0], tmp[1], tmp[2], tmp[3]);
                    }
                }
                *reinterpret_cast<float4*>(&dst[row * SM_B_STRIDE + colBaseB]) = val;
            }
        }
        __syncthreads();
        #pragma unroll
        for (int c = 0; c < COLTILES; ++c) {
            int curBuf = c & 1;
            int nextC = c + 1;
            if (nextC < COLTILES) {
                // Prefetch next N-tile of B into the other buffer while we compute with the
                // current buffer; the global-memory latency of this load overlaps with the
                // subsequent independent FMA compute below (software pipelining).
                int nextBuf = curBuf ^ 1;
                int blockColNext = colBase + nextC * BN;
                float* dst = Bs + (size_t)nextBuf * BK * SM_B_STRIDE;
                const int numBvec = (BK * BN) / 4;
                for (int i = tid; i < numBvec; i += numThreads) {
                    int row = (i * 4) / BN;
                    int colBaseB = (i * 4) % BN;
                    int globalRow = kBase + row;
                    int globalCol = blockColNext + colBaseB;
                    float4 val = make_float4(0.f, 0.f, 0.f, 0.f);
                    if (globalRow < K) {
                        if (globalCol + 3 < N) {
                            val = *reinterpret_cast<const float4*>(&B[(size_t)globalRow * N + globalCol]);
                        } else {
                            float tmp[4] = {0.f, 0.f, 0.f, 0.f};
                            #pragma unroll
                            for (int j = 0; j < 4; ++j) {
                                int cc = globalCol + j;
                                if (cc < N) tmp[j] = B[(size_t)globalRow * N + cc];
                            }
                            val = make_float4(tmp[0], tmp[1], tmp[2], tmp[3]);
                        }
                    }
                    *reinterpret_cast<float4*>(&dst[row * SM_B_STRIDE + colBaseB]) = val;
                }
            }
            float* BsCur = Bs + (size_t)curBuf * BK * SM_B_STRIDE;
            #pragma unroll
            for (int k = 0; k < BK; ++k) {
                float aReg[TM];
                #pragma unroll
                for (int i = 0; i < TM; ++i)
                    aReg[i] = As[(ty * TM + i) * SM_A_STRIDE + k];
                float bReg[TN];
                float4 bVec0 = *reinterpret_cast<const float4*>(&BsCur[k * SM_B_STRIDE + tx * TN]);
                float4 bVec1 = *reinterpret_cast<const float4*>(&BsCur[k * SM_B_STRIDE + tx * TN + 4]);
                bReg[0] = bVec0.x; bReg[1] = bVec0.y; bReg[2] = bVec0.z; bReg[3] = bVec0.w;
                bReg[4] = bVec1.x; bReg[5] = bVec1.y; bReg[6] = bVec1.z; bReg[7] = bVec1.w;
                #pragma unroll
                for (int i = 0; i < TM; ++i)
                    #pragma unroll
                    for (int j = 0; j < TN; ++j)
                        acc[c][i][j] += aReg[i] * bReg[j];
            }
            __syncthreads();
        }
    }
    #pragma unroll
    for (int c = 0; c < COLTILES; ++c) {
        int blockCol = colBase + c * BN;
        #pragma unroll
        for (int i = 0; i < TM; ++i) {
            int row = blockRow + ty * TM + i;
            if (row < M) {
                int colStart = blockCol + tx * TN;
                if (colStart + TN <= N) {
                    // Fully in-bounds: vectorized float4 stores (TN == 8 -> two float4 writes)
                    float4 v0 = make_float4(acc[c][i][0], acc[c][i][1], acc[c][i][2], acc[c][i][3]);
                    float4 v1 = make_float4(acc[c][i][4], acc[c][i][5], acc[c][i][6], acc[c][i][7]);
                    *reinterpret_cast<float4*>(&C[(size_t)row * N + colStart])     = v0;
                    *reinterpret_cast<float4*>(&C[(size_t)row * N + colStart + 4]) = v1;
                } else {
                    #pragma unroll
                    for (int j = 0; j < TN; ++j) {
                        int col = colStart + j;
                        if (col < N) {
                            C[(size_t)row * N + col] = acc[c][i][j];
                        }
                    }
                }
            }
        }
    }
}
torch::Tensor cute_matmul(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.is_cuda() && B.is_cuda(), "A and B must be CUDA tensors");
    TORCH_CHECK(A.dim() == 2 && B.dim() == 2, "A and B must be 2D");
    TORCH_CHECK(A.scalar_type() == at::kFloat && B.scalar_type() == at::kFloat,
                "Expect float32 tensors");
    int M = (int)A.size(0);
    int K = (int)A.size(1);
    int N = (int)B.size(1);
    TORCH_CHECK((int)B.size(0) == K, "B.size(0) must equal A.size(1)");
    auto A_c = A.contiguous();
    auto B_c = B.contiguous();
    auto C   = torch::empty({M, N}, A.options());
    dim3 block(BN / TN, BM / TM);
    dim3 grid((N + BN * COLTILES - 1) / (BN * COLTILES), (M + BM - 1) / BM);
    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
    size_t smem_bytes = (size_t)BM * SM_A_STRIDE * sizeof(float)
                       + 2ull * (size_t)BK * SM_B_STRIDE * sizeof(float);
    static bool attr_set = false;
    if (!attr_set) {
        cudaFuncSetAttribute(cute_matmul_kernel, cudaFuncAttributeMaxDynamicSharedMemorySize, (int)smem_bytes);
        attr_set = true;
    }
    cute_matmul_kernel<<<grid, block, smem_bytes, stream>>>(
        A_c.data_ptr<float>(), B_c.data_ptr<float>(), C.data_ptr<float>(), M, N, K);
    TORCH_CHECK(cudaGetLastError() == cudaSuccess, "CUTE matmul launch failed");
    return C;
}
"""

cute_ext = load_inline(
    name="cute_matmul_tall_skinny_ext",
    cpp_sources=cpp_decl,
    cuda_sources=cuda_src,
    functions=["cute_matmul"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=["/workspace/cutegen_test/cutegen/cutlass/include"],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()
        self._ext = cute_ext

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
